      en: ["The national park was established in 1995", "It covers a total area of approximately 23,498 hectares", "Serves as an elephant corridor between Yala and Udawalawe", "More than 180 bird species are native to the park", "The Lunugamvehera reservoir is central to the park", "Over 20 different fish species have been documented"],
      es: ["Fundado el 8 de diciembre de 1995.", "Superficie: 235 km².", "Precipitación: aprox. 1250 mm anuales.", "Elevación máxima: aprox. 150 m sobre el nivel del mar.", "Población de elefantes: estimaciones de 50-100 individuos.", "Número de especies de aves: más de 200."],
      pt: ["Fundado a 8 de dezembro de 1995.", "Superfície: 235 km².", "Precipitação: aprox. 1250 mm anuais.", "Elevação máxima: aprox. 150 m acima do nível do mar.", "População de elefantes: estimativas de 50-100 indivíduos.", "Número de espécies de aves: mais de 200."],
      fr: ["Fondé le 8 décembre 1995.", "Superficie : 235 km².", "Précipitations : env. 1250 mm par an.", "Altitude maximale : env. 150 m au-dessus du niveau de la mer.", "Population d'éléphants : estimations de 50-100 individus.", "Nombre d'espèces d'oiseaux : plus de 200."],
