      fr: ["Fondé en 1983.", "Superficie : 588 km².", "Point culminant : env. 300 m.", "Précipitations annuelles : 1200-1500 mm.", "Population d'éléphants : env. 100-200 animaux.", "Nombre d'espèces de plantes endémiques : 32."],
