    name: { de: "Botanischer Garten Peradeniya", hu: "Peradeniya Királyi Botanikus Kert", ro: "Grădina Botanică Regală Peradeniya", en: "Royal Botanical Gardens Peradeniya"},
    image: "/poi-images/royal-botanical-gardens-peradeniya-life-v2.webp",
    description: { de: "Der größte botanische Garten des Landes, berühmt für seine Orchideensammlung und die riesige Javanische Feige.", hu: "Az ország legnagyobb botanikus kertje, amely orchideagyűjteményéről és hatalmas jávai fügefájáról híres.", ro: "Cea mai mare grădină botanică din țară, faimoasă pentru colecția sa de orhidee și uriașul smochin de Java.", en: "The largest botanical garden in the country, famous for its orchid collection and massive Javan fig tree." , es: "El jardín botánico más grande del país, famoso por su colección de orquídeas y la higuera gigante de Java.", pt: "O maior jardim botânico do país, famoso pela sua coleção de orquídeas e pela figueira-de-java gigante.", fr: "Le plus grand jardin botanique du pays, célèbre pour sa collection d'orchidées et le figuier géant de Java."},
    facts: {
      de: ["Gegründet im Jahr 1843", "Besitzt ein großes Orchideenhaus", "Zieht jährlich Millionen Besucher an"],
      hu: ["1843-ban alapították", "Nagy orchideaházzal rendelkezik", "Évente több millió látogatót vonz"],
      ro: ["Fondată în 1843", "Deține o mare seră de orhidee", "Atrage milioane de vizitatori anual"],
      en: ["Founded in 1843", "Features a large orchid house", "Attracts millions of visitors annually"],
      es: ["Fundado en 1843", "Tiene una gran casa de orquídeas", "Atrae a millones de visitantes al año"],
      pt: ["Fundado em 1843", "Possui uma grande casa de orquídeas", "Atrai milhões de visitantes anualmente"],
      fr: ["Fondé en 1843", "Possède une grande serre aux orchidées", "Attire des millions de visiteurs par an"],
    }, image: "/poi-images/royal-botanical-gardens-peradeniya-life-v2.webp",
    descriptionAdvanced: {
      de: "Die Royal Botanical Gardens in Peradeniya sind der größte und bekannteste botanische Garten Sri Lankas und liegen in der Nähe der Stadt Kandy. Auf einer Fläche von etwa 59 Hektar wird der Garten an drei Seiten vom Mahaweli-Fluss, dem längsten Fluss des Landes, umschlossen. Die Ursprünge des Geländes reichen bis in das 14. Jahrhundert unter König Wickramabahu III. zurück, doch die moderne Anlage wurde 1821 von den Briten offiziell gegründet. Der Garten beherbergt eine vielfältige Sammlung von über 4.000 Pflanzenarten, darunter ein weltberühmtes Orchideenhaus, einen riesigen javanischen Feigenbaum und eine Allee aus Königspalmen. Zudem dient der Park als Zentrum für wissenschaftliche Forschung und beherbergt das Nationale Herbarium von Sri Lanka. Besucher können bedeutende historische Pflanzungen bewundern, wie einen Kanonenkugelbaum, der 1901 von König Georg V. und Königin Mary gepflanzt wurde.",
      hu: "A Peradeniyában található Királyi Botanikus Kert Sri Lanka legnagyobb és legismertebb botanikus kertje, amely Kandy városának közelében helyezkedik el. A mintegy 59 hektáros területet három oldalról az ország leghosszabb folyója, a Mahaweli-folyó határolja. A helyszín eredete a 14. századig, III. Wickramabahu király uralkodásáig nyúlik vissza, de a modern létesítményt a britek hivatalosan 1821-ben alapították. A kert több mint 4000 növényfajnak ad otthont, köztük egy világhírű orchideaháznak, egy hatalmas jávai fügefának és egy királypálma-sornak. A botanikus kert tudományos kutatóközpontként is funkcionál, itt található Sri Lanka Nemzeti Herbáriuma is. A látogatók olyan történelmi jelentőségű ültetéseket is megtekinthetnek, mint az V. György király és Mária királyné által 1901-ben ültetett ágyúgolyófa.",
      ro: "Grădina Botanică Regală din Peradeniya este cea mai mare și mai renumită grădină botanică din Sri Lanka, situată în apropierea orașului Kandy. Întinzându-se pe aproximativ 59 de hectare, grădina este mărginită pe trei laturi de râul Mahaweli, cel mai lung râu din țară. Originile sitului datează din secolul al XIV-lea, în timpul domniei regelui Wickramabahu al III-lea, însă facilitatea modernă a fost înființată oficial de britanici în 1821. Aceasta găzduiește o colecție diversă de peste 4.000 de specii de plante, inclusiv o casă de orhidee celebră la nivel mondial, un smochin javanez uriaș și o alee de palmieri regali. Grădina servește, de asemenea, ca centru de cercetare științifică, adăpostind Herbarul Național din Sri Lanka. Vizitatorii pot observa plantări istorice semnificative, cum ar fi un arbore-ghiulea plantat de regele George al V-lea și regina Maria în 1901.",
      en: "The Royal Botanical Gardens in Peradeniya is the largest and most renowned botanical garden in Sri Lanka, situated near the city of Kandy. Spanning approximately 147 acres, the gardens are bordered on three sides by the Mahaweli River, the longest river in the country. The site's origins date back to the 14th century during the reign of King Wickramabahu III, but the modern facility was formally established by the British in 1821. It houses a diverse collection of over 4,000 plant species, including a world-famous orchid house, a massive Javan fig tree, and an avenue of royal palms. The gardens also serve as a center for scientific research, hosting the National Herbarium of Sri Lanka. Visitors can observe significant historical plantings, such as a cannonball tree planted by King George V and Queen Mary in 1901.",
      es: "Los Reales Jardines Botánicos de Peradeniya se encuentran a unos 5,5 kilómetros al oeste de Kandy, Sri Lanka. Fundados en 1821, abarcan 59 hectáreas. Los jardines son famosos por su extensa colección de plantas tropicales, incluyendo una impresionante colección de más de 300 especies de orquídeas. El jardín también alberga un callejón de bambú gigante, el árbol de higo de Java (Ficus benghalensis) y muchas especies de palmeras. Funciona como un centro de investigación y educación. El terreno está aterrazado y lo atraviesa el río Mahaweli. Más de 1,5 millones de personas visitan los jardines anualmente.",
      pt: "Os Jardins Botânicos Reais de Peradeniya estão localizados a cerca de 5,5 quilómetros a oeste de Kandy, no Sri Lanka. Fundados em 1821, abrangem 59 hectares. Os jardins são famosos pela sua extensa coleção de plantas tropicais, incluindo uma impressionante coleção de mais de 300 espécies de orquídeas. O jardim também alberga uma alameda de bambu gigante, a figueira-de-java (Ficus benghalensis) e muitas espécies de palmeiras. Funciona como um centro de investigação e educação. O terreno é em socalcos e é atravessado pelo rio Mahaweli. Mais de 1,5 milhões de pessoas visitam os jardins anualmente.",
      fr: "Les jardins botaniques royaux de Peradeniya sont situés à environ 5,5 kilomètres à l'ouest de Kandy, au Sri Lanka. Fondés en 1821, ils s'étendent sur 59 hectares. Les jardins sont célèbres pour leur vaste collection de plantes tropicales, dont une impressionnante collection de plus de 300 espèces d'orchidées. Le jardin abrite également une allée de bambous géants, le figuier de Java (Ficus benghalensis) et de nombreuses espèces de palmiers. Il sert de centre de recherche et d'éducation. Le terrain est en terrasses et traversé par la rivière Mahaweli. Plus de 1,5 million de personnes visitent les jardins chaque année.",
    },
