      hu: ["1821-ben alapították hivatalosan", "Összesen 59 hektáron terül el", "Több mint 4000 növényfaj otthona", "A Mahaweli-folyó kanyarulatában fekszik", "Világhírű orchideaház 300 fajjal", "460 méteres tengerszint feletti magasság"],
      ro: ["Înființată oficial în anul 1821", "Suprafață totală de 59 de hectare", "Găzduiește peste 4000 de specii", "Mărginită de râul Mahaweli", "Casă de orhidee cu peste 300 de tipuri", "Altitudine de 460 de metri"],
      en: ["Officially established in 1821", "Total area of 147 acres", "Home to over 4,000 plant species", "Bordered by the Mahaweli River", "Famous Orchid House with 300 varieties", "Situated at 460 meters altitude"],
