      fr: ["Fondé en 1821.", "Superficie : 59 hectares.", "Espèces d'orchidées : plus de 300.", "Visiteurs par an : plus de 1,5 million.", "Espèces de palmiers : plus de 100.", "Tracé à l'origine comme jardin royal en 1375."],
