    name: { de: "Botanischer Garten Henarathgoda", hu: "Henarathgoda Botanikus Kert", ro: "Grădina Botanică Henarathgoda", en: "Henarathgoda Botanical Garden"},
    image: "/poi-images/henarathgoda-botanical-garden-life-v2.webp",
    description: { de: "Ein historischer Garten, in dem der erste Kautschukbaum Südasiens gepflanzt wurde.", hu: "Történelmi kert, ahol Dél-Ãzsia első kaucsukfáját elültették.", ro: "O grădină istorică unde a fost plantat primul arbore de cauciuc din Asia de Sud.", en: "A historical garden where the first rubber tree in South Asia was planted." , es: "Un jardín histórico donde se plantó el primer árbol de caucho del sur de Asia.", pt: "Um jardim histórico onde foi plantada a primeira árvore de borracha do sul da Ásia.", fr: "Un jardin historique où a été planté le premier hévéa d'Asie du Sud."},
    facts: {
      de: ["Gegründet im Jahr 1876", "Heimat seltener tropischer Bäume", "Wichtig für die frühe Kautschukindustrie"],
      hu: ["1876-ban alapították", "Ritka trópusi fák otthona", "Fontos volt a korai gumiipar számára"],
      ro: ["Fondată în 1876", "Găzduiește arbori tropicali rari", "Importantă pentru industria timpurie a cauciucului"],
      en: ["Established in 1876", "Home to rare tropical trees", "Important to the early rubber industry"],
      es: ["Fundado en 1876", "Hogar de árboles tropicales raros", "Importante para la industria temprana del caucho"],
      pt: ["Fundado em 1876", "Lar de árvores tropicais raras", "Importante para a indústria primitiva da borracha"],
      fr: ["Fondé en 1876", "Abrite des arbres tropicaux rares", "Important pour l'industrie du caoutchouc précoce"],
    }, image: "/poi-images/henarathgoda-botanical-garden-life-v2.webp",
    descriptionAdvanced: {
      de: "Der Botanische Garten von Henarathgoda in Gampaha nimmt einen einzigartigen Platz in der Wirtschaftsgeschichte Asiens ein, da hier die ersten Kautschukbäume Sri Lankas gepflanzt wurden. Der 1876 gegründete Garten wurde speziell für Kautschuksetzlinge (Hevea brasiliensis) angelegt, die über die Kew Gardens in London aus Brasilien kamen. Dieses erfolgreiche Experiment legte den Grundstein für die massive Kautschukindustrie, die die Wirtschaft von Sri Lanka und Südostasien veränderte. Der Garten umfasst etwa 17 Hektar und beherbergt eine Vielzahl tropischer Tieflandpflanzen, darunter Palmen, Mahagoni- und Ebenholzbäume. Obwohl der ursprüngliche Kautschukbaum von 1876 schließlich abstarb, sind seine Überreste als historisches Denkmal erhalten. Der Garten liegt auf einer Höhe von nur 33 Metern und bietet eine Umgebung, die sich deutlich von den Hochlandgärten unterscheidet. Zudem gibt es einen kleinen See und Bootsfahrten für Besucher.",
      hu: "A Gampahában található Henarathgoda Botanikus Kert különleges helyet foglal el Ázsia gazdaságtörténetében, mivel itt ültették el az első gumifákat Sri Lankán. Az 1876-ban alapított kertet kifejezetten a Brazíliából a londoni Kew Gardens-en keresztül érkező gumifa-csemeték (Hevea brasiliensis) befogadására hozták létre. Ez a sikeres kísérlet alapozta meg a hatalmas gumiipart, amely átformálta Sri Lanka és Délkelet-Ázsia gazdaságát. A kert körülbelül 17 hektáron terül el, és számos trópusi alföldi növényfajt mutat be, köztük pálmákat, mahagónit és ébenfákat. Bár az eredeti, 1876-ban ültetett gumifa végül elpusztult, maradványait történelmi emlékműként őrzik. A kert mindössze 33 méteres tengerszint feletti magasságban fekszik, ami a hegyvidéki kertektől eltérő környezetet biztosít. A területen egy kis tó is található, ahol a látogatók csónakázhatnak.",
      ro: "Grădina Botanică Henarathgoda, situată în Gampaha, ocupă un loc unic în istoria economică a Asiei, fiind locul unde au fost plantați primii arbori de cauciuc din Sri Lanka. Înființată în 1876, grădina a fost creată special pentru a găzdui răsaduri de cauciuc (Hevea brasiliensis) aduse din Brazilia prin Kew Gardens din Londra. Acest experiment de succes a pus bazele industriei masive a cauciucului care a transformat economiile din Sri Lanka și Asia de Sud-Est. Grădina acoperă aproximativ 17 hectare și prezintă o varietate de floră tropicală de joasă altitudine, inclusiv palmieri, mahon și arbori de abanos. Deși arborele original de cauciuc plantat în 1876 a murit în cele din urmă, rămășițele sale sunt păstrate ca monument istoric. Grădina este situată la o altitudine de doar 33 de metri, oferind un mediu distinct față de grădinile montane. De asemenea, dispune de un mic lac și facilități pentru plimbări cu barca.",
      en: "Henarathgoda Botanical Garden, located in Gampaha, holds a unique place in the economic history of Asia as the site where the first rubber trees were planted in Sri Lanka. Established in 1876, the garden was created specifically to accommodate rubber seedlings (Hevea brasiliensis) brought from Brazil via Kew Gardens in London. This successful experiment laid the foundation for the massive rubber industry that transformed the economies of Sri Lanka and Southeast Asia. The garden covers approximately 43 acres and features a variety of tropical low-country flora, including palms, mahogany, and ebony trees. Although the original rubber tree planted in 1876 eventually died, its remains are preserved as a historical monument. The garden is situated at an altitude of only 33 meters, providing an environment distinct from the highland gardens. It also features a small lake and a boat ride facility for visitors.",
      es: "El Jardín Botánico de Henarathgoda se encuentra en Gampaha, a unos 24 kilómetros de Colombo, a una altitud de solo 10 metros sobre el nivel del mar. Fue fundado en 1876, principalmente para la introducción del árbol del caucho (Hevea brasiliensis) en Sri Lanka. El jardín se extiende sobre 17 hectáreas y alberga una colección de cultivos tropicales, como cacao, café y nuez moscada. El clima húmedo de las tierras bajas favorece su crecimiento. El jardín es famoso por su gran población de palmeras y bambúes. Jugó un papel clave en el desarrollo agrícola del país. Hoy sirve como centro de investigación botánica.",
      pt: "O Jardim Botânico de Henarathgoda situa-se em Gampaha, a cerca de 24 quilómetros de Colombo, a uma altitude de apenas 10 metros acima do nível do mar. Foi fundado em 1876, principalmente para a introdução da seringueira (Hevea brasiliensis) no Sri Lanka. O jardim estende-se por 17 hectares e alberga uma coleção de culturas tropicais, como cacau, café e noz-moscada. O clima húmido das terras baixas favorece o seu crescimento. O jardim é famoso pela sua grande população de palmeiras e bambus. Desempenhou um papel fundamental no desenvolvimento agrícola do país. Hoje, serve como centro de investigação botânica.",
      fr: "Le jardin botanique de Henarathgoda est situé à Gampaha, à environ 24 kilomètres de Colombo, à une altitude de seulement 10 mètres au-dessus du niveau de la mer. Il a été fondé en 1876, principalement pour l'introduction de l'hévéa (Hevea brasiliensis) au Sri Lanka. Le jardin s'étend sur 17 hectares et abrite une collection de cultures tropicales, telles que le cacao, le café et la noix de muscade. Le climat humide des basses terres favorise leur croissance. Le jardin est célèbre pour sa grande population de palmiers et de bambous. Il a joué un rôle clé dans le développement agricole du pays. Aujourd'hui, il sert de centre de recherche botanique.",
    },
