    type: "park",
    parent: "LK-11",
    coords: [79.8612, 6.9118],
    name: { de: "Viharamahadevi-Park", hu: "Viharamahadevi Park", ro: "Parcul Viharamahadevi", en: "Viharamahadevi Park"},
    image: "/poi-images/viharamahadevi-park-life-v2.webp",
    description: { de: "Der größte und älteste öffentliche Park in Colombo, mit einem großen Buddha und Wasserfontänen.", hu: "Colombo legnagyobb és legrégebbi nyilvános parkja, egy hatalmas Buddha-szoborral és szökőkutakkal.", ro: "Cel mai mare și mai vechi parc public din Colombo, cu o statuie mare a lui Buddha și fântâni arteziene.", en: "The largest and oldest public park in Colombo, featuring a large Buddha statue and water fountains." , es: "El parque público más grande y antiguo de Colombo, con un gran Buda y fuentes de agua.", pt: "O maior e mais antigo parque público de Colombo, com um grande Buda e fontes de água.", fr: "Le plus grand et le plus ancien parc public de Colombo, avec un grand Bouddha et des fontaines d'eau."},
    facts: {
      de: ["Früher als Victoria Park bekannt", "Gegenüber dem Rathaus gelegen", "Beliebt für Picknicks und Spaziergänge"],
      hu: ["Korábban Victoria Park néven volt ismert", "A városházával szemben található", "Népszerű piknikező- és sétálóhely"],
      ro: ["Fostul parc Victoria", "Situat vizavi de Primărie", "Popular pentru picnicuri și plimbări"],
      en: ["Formerly known as Victoria Park", "Located opposite the Town Hall", "Popular for picnics and walks"],
      es: ["Anteriormente conocido como Victoria Park", "Situado frente al Ayuntamiento", "Popular para picnics y paseos"],
      pt: ["Anteriormente conhecido como Victoria Park", "Localizado em frente à Câmara Municipal", "Popular para piqueniques e caminhadas"],
      fr: ["Anciennement connu sous le nom de Victoria Park", "Situé en face de la mairie", "Populaire pour les pique-niques et les promenades"],
    }, image: "/poi-images/viharamahadevi-park-life-v2.webp",
    descriptionAdvanced: {
      de: "Der Viharamahadevi Park ist der älteste und größte öffentliche Park in Colombo und befindet sich im angesehenen Viertel Cinnamon Gardens. Ursprünglich von den Briten Victoria Park genannt, wurde er 1958 zu Ehren von Königin Viharamahadevi, der heldenhaften Mutter von König Dutugemunu, umbenannt. Der Park wurde auf Land errichtet, das der Philanthrop Charles Henry de Soysa gespendet hatte, und diente während des Zweiten Weltkriegs als Militärstützpunkt für die britische Armee. Heute ist er das Herzstück der städtischen Grünflächen und verfügt über eine große goldene Buddha-Statue an seinem südlichen Eingang. Das Gelände umfasst gepflegte Rasenflächen, blühende Bäume wie den Flamboyant und die Cassia sowie mehrere Brunnen. Er liegt direkt neben dem Nationalmuseum von Colombo und dem Rathaus, was ihn zu einem zentralen Punkt für das kulturelle und bürgerliche Leben macht. Der Park beherbergt auch ein Gefallenendenkmal und ein Freiluftstadion.",
      hu: "A Viharamahadevi Park Colombo legrégebbi és legnagyobb nyilvános parkja, amely a neves Cinnamon Gardens negyedben található. Eredetileg a britek Victoria Parknak nevezték el, majd 1958-ban keresztelték át Viharamahadevi királyné, Dutugemunu király hősies édesanyja tiszteletére. A parkot a filantróp Charles Henry de Soysa által adományozott földterületen alakították ki, és a második világháború alatt a brit hadsereg katonai bázisaként szolgált. Ma a város zöldterületeinek központja, déli bejáratánál egy hatalmas arany Buddha-szoborral. A területen gondozott pázsit, virágzó fák (például Flamboyant és Cassia) és több szökőkút található. Közvetlenül a Colombo Nemzeti Múzeum és a Városháza mellett helyezkedik el, így a kulturális és társadalmi élet gyújtópontja. A park egy háborús emlékműnek és egy szabadtéri stadionnak is otthont ad.",
      ro: "Parcul Viharamahadevi este cel mai vechi și cel mai mare parc public din Colombo, situat în prestigiosul cartier Cinnamon Gardens. Numit inițial Parcul Victoria de către britanici, a fost redenumit în 1958 în onoarea reginei Viharamahadevi, mama eroică a regelui Dutugemunu. Parcul a fost construit pe terenul donat de filantropul Charles Henry de Soysa și a servit ca bază militară pentru armata britanică în timpul celui de-al Doilea Război Mondial. Astăzi, este elementul central al spațiilor verzi ale orașului, având o statuie mare de aur a lui Buddha la intrarea sa sudică. Terenul include peluze bine întreținute, arbori înfloriți precum Flamboyant și Cassia, și mai multe fântâni. Este situat adiacent Muzeului Național din Colombo și Primăriei, fiind un punct central pentru viața culturală și civică. Parcul găzduiește, de asemenea, un cenotaf memorial de război și un stadion în aer liber.",
      en: "Viharamahadevi Park is the oldest and largest public park in Colombo, located in the prestigious Cinnamon Gardens district. Originally named Victoria Park by the British, it was renamed in 1958 in honor of Queen Viharamahadevi, the heroic mother of King Dutugemunu. The park was built on land donated by the philanthropist Charles Henry de Soysa and served as a military base for the British Army during World War World II. Today, it is a centerpiece of the city's green space, featuring a large golden statue of Buddha at its southern entrance. The grounds include manicured lawns, flowering trees like the Flamboyant and Cassia, and several fountains. It is situated adjacent to the National Museum of Colombo and the Town Hall, making it a central point for cultural and civic life. The park also hosts a war memorial cenotaph and an open-air stadium for public events.",
      es: "El Viharamahadevi Park en Colombo es el parque público más antiguo y grande de la ciudad. Fue creado en la década de 1860 y originalmente se llamó Victoria Park, siendo renombrado en honor a la madre del Rey Vijaya. El parque abarca unas 15 hectáreas y ofrece un retiro tranquilo en el corazón de la capital. Alberga un gran estanque, árboles centenarios y monumentos, incluida una estatua de Viharamahadevi. Es conocido por su avifauna y la iluminación navideña anual. Sirve como área de recreación con parques infantiles y senderos. Fue diseñado por la administración colonial británica y es un lugar popular para las familias.",
      pt: "O Viharamahadevi Park em Colombo é o mais antigo e maior parque público da cidade. Foi criado na década de 1860 e originalmente chamado de Victoria Park, sendo renomeado em honra da mãe do Rei Vijaya. O parque abrange cerca de 15 hectares e oferece um retiro tranquilo no coração da capital. Alberga um grande lago, árvores centenárias e monumentos, incluindo uma estátua de Viharamahadevi. É conhecido pela sua avifauna e pela iluminação de Natal anual. Serve como área de recreação com parques infantis e trilhos. Foi desenhado pela administração colonial britânica e é um local popular para famílias.",
      fr: "Le parc Viharamahadevi à Colombo est le plus ancien et le plus grand parc public de la ville. Il a été créé dans les années 1860 et s'appelait à l'origine Victoria Park, avant d'être renommé en l'honneur de la mère du roi Vijaya. Le parc s'étend sur environ 15 hectares et offre une retraite paisible au cœur de la capitale. Il abrite un grand étang, des arbres centenaires et des monuments, dont une statue de Viharamahadevi. Il est connu pour son avifaune et ses illuminations de Noël annuelles. Il sert de zone de loisirs avec des aires de jeux et des sentiers. Il a été conçu par l'administration coloniale britannique et est un lieu apprécié des familles.",
    },
