      ro: ["Cel mai vechi parc public din Colombo", "Redenumit în anul 1958", "Situat lângă Primăria din Colombo", "Teren donat de Charles Henry de Soysa", "Include o statuie mare de aur a lui Buddha", "A servit ca bază militară în Al Doilea Război Mondial"],
      en: ["Oldest public park in Colombo", "Renamed in the year 1958", "Located near Colombo Town Hall", "Built on land donated by C. H. de Soysa", "Features a large golden Buddha statue", "Used as a military base in WWII"],
      es: ["Creado en la década de 1860.", "Superficie: 15 hectáreas.", "Nombre original: Victoria Park.", "Renombramiento: 1999.", "Visitantes anuales: más de 1 millón.", "Alberga más de 40 árboles monumentales."],
      pt: ["Criado na década de 1860.", "Área: 15 hectares.", "Nome original: Victoria Park.", "Renomeação: 1999.", "Visitantes anuais: mais de 1 milhão.", "Abriga mais de 40 árvores monumentais."],
      fr: ["Créé dans les années 1860.", "Superficie : 15 hectares.", "Nom original : Victoria Park.", "Renommage : 1999.", "Visiteurs par an : plus d'un million.", "Abrite plus de 40 arbres monumentaux."],
