    name: { de: "Safari-Park Ridiyagama", hu: "Ridiyagama Szafaripark", ro: "Parcul de Safari Ridiyagama", en: "Ridiyagama Safari Park"},
    image: "/poi-images/ridiyagama-safari-park-life-v2.webp",
    description: { de: "Ein weitläufiger Safaripark mit Freigehegen für afrikanische Löwen, asiatische Elefanten und bengalische Tiger.", hu: "Kiterjedt szafaripark hatalmas kifutókkal az afrikai oroszlánok, ázsiai elefántok és bengáli tigrisek számára.", ro: "Un parc de safari extins cu incinte mari în aer liber pentru lei africani, elefanți asiatici și tigri bengalezi.", en: "An expansive safari park with open-air enclosures for African lions, Asian elephants, and Bengal tigers." , es: "Un extenso parque safari con recintos abiertos para leones africanos, elefantes asiáticos y tigres de Bengala.", pt: "Um extenso parque safari com recintos abertos para leões africanos, elefantes asiáticos e tigres de Bengala.", fr: "Un vaste parc safari avec des enclos ouverts pour les lions africains, les éléphants d'Asie et les tigres du Bengale."},
    facts: {
      de: ["Der erste Safari-Park in Sri Lanka", "Eröffnet im Jahr 2016", "Umfasst über 500 Hektar Land"],
      hu: ["Az első szafaripark Srí Lankán", "2016-ban nyitotta meg kapuit", "Több mint 500 hektáros területen fekszik"],
      ro: ["Primul parc de safari din Sri Lanka", "Deschis în 2016", "Se întinde pe peste 500 de hectare"],
      en: ["The first safari park in Sri Lanka", "Opened in 2016", "Spans over 500 acres of land"],
      es: ["El primer parque safari en Sri Lanka", "Inaugurado en 2016", "Abarca más de 500 hectáreas de tierra"],
      pt: ["O primeiro parque safari no Sri Lanka", "Inaugurado em 2016", "Abrange mais de 500 hectares de terra"],
      fr: ["Le premier parc safari au Sri Lanka", "Inauguré en 2016", "Couvre plus de 500 hectares de terrain"],
    }, image: "/poi-images/ridiyagama-safari-park-life-v2.webp",
    descriptionAdvanced: {
      de: "Der Ridiyagama Safari Park wurde am 28. März 2016 eröffnet und ist Sri Lankas erster künstlich angelegter Freiluft-Safaripark. Er befindet sich in Ambalantota im Distrikt Hambantota, umfasst etwa 200 Hektar und wird vom Ministerium für Nationale Zoologische Gärten verwaltet. Die Anlage ist in mehrere spezialisierte Zonen unterteilt, darunter eine 14 Hektar große Löwenzone, eine 22 Hektar große Zone für sri-lankische Elefanten und eine Weltzone für verschiedene Huftiere. Besucher durchqueren den Park in gesicherten Bussen, was es ihnen ermöglicht, Tiere wie Bengal-Tiger, Leoparden und Zebras in einem halbnatürlichen Lebensraum zu beobachten. Der Park wurde entworfen, um den Tieren im Vergleich zu herkömmlichen Zoos eine artgerechtere und geräumigere Umgebung zu bieten und gleichzeitig den Naturschutz und die Bildung zu fördern. Er hat sich zu einem bedeutenden Tourismuszentrum im Süden Sri Lankas entwickelt und stärkt die lokale Wirtschaft erheblich. Zukünftige Pläne sehen Zonen für Geparden und Bären vor.",
      hu: "A 2016. március 28-án megnyitott Ridiyagama Safari Park Sri Lanka legelső mesterségesen kialakított, szabadtéri szafariparkja. A Hambantota körzetben, Ambalantotában található park körülbelül 200 hektáron terül el, és a Nemzeti Állatkertek Osztálya kezeli. A létesítmény több speciális zónára oszlik, többek között egy 14 hektáros oroszlánzónára, egy 22 hektáros sri lankai elefántzónára és egy Világzónára a különféle növényevők számára. A látogatók biztonságos buszokkal járják be a parkot, így félig természetes élőhelyükön figyelhetik meg a bengáli tigriseket, leopárdokat és zebrákat. A parkot azért hozták létre, hogy a hagyományos állatkertekhez képest humánusabb és tágasabb környezetet biztosítson az állatoknak, miközben elősegíti a vadvédelem és az oktatás ügyét. Dél-Sri Lanka jelentős turisztikai központjává vált, ami fellendítette a helyi gazdaságot. A jövőbeli tervek között szerepel gepárd- és medvezónák kialakítása is.",
      ro: "Parcul Safari Ridiyagama, deschis pe 28 martie 2016, este primul parc safari în aer liber creat de om din Sri Lanka. Situat în Ambalantota, în districtul Hambantota, parcul se întinde pe aproximativ 200 de hectare și este administrat de Departamentul Grădinilor Zoologice Naționale. Facilitatea este împărțită în mai multe zone specializate, inclusiv o Zonă a Leilor de 14 hectare, o Zonă a Elefanților din Sri Lanka de 22 hectare și o Zonă Mondială pentru diverse erbivore. Vizitatorii traversează parcul în autobuze securizate, permițându-le să observe animale precum tigri bengalezi, leoparzi și zebre într-un habitat semi-natural. Parcul a fost conceput pentru a oferi un mediu mai uman și mai spațios pentru animale în comparație cu grădinile zoologice tradiționale, promovând în același timp conservarea și educația. A devenit un centru turistic major în sudul Sri Lankăi, stimulând semnificativ economia locală. Planurile viitoare includ zone pentru gheparzi și urși.",
      en: "Ridiyagama Safari Park, opened on March 28, 2016, is Sri Lanka's first ever man-made open-air safari park. Located in Ambalantota in the Hambantota District, the park spans approximately 500 acres and is managed by the Department of National Zoological Gardens. The facility is divided into several specialized zones, including a 35-acre Lion Zone, a 54-acre Sri Lankan Elephant Zone, and a World Zone for various herbivores. Visitors traverse the park in secure buses, allowing them to observe animals such as Bengal tigers, leopards, and zebras in a semi-natural habitat. The park was designed to provide a more humane and spacious environment for animals compared to traditional zoos while promoting wildlife conservation and education. It has become a major tourism hub in southern Sri Lanka, significantly boosting the local economy. Future expansion plans include zones for cheetahs and bears to further diversify the park's inhabitants.",
      es: "El Ridiyagama Safari Park se encuentra cerca de Hambantota, en el sur de Sri Lanka, y abrió en 2016. Con unas 200 hectáreas, es el primer safari de la isla diseñado con recintos abiertos. El parque se divide en zonas que albergan leones, tigres, osos, jirafas y cebras. Algunos animales fueron importados de otros zoológicos o rescatados. El parque ofrece safaris en vehículo, con el objetivo de mostrar la biodiversidad y promover la educación ambiental, colaborando con proyectos de conservación locales.",
      pt: "O Ridiyagama Safari Park está localizado perto de Hambantota, no sul do Sri Lanka, e abriu em 2016. Com cerca de 200 hectares, é o primeiro safari da ilha concebido com recintos abertos. O parque está dividido em zonas que albergam leões, tigres, ursos, girafas e zebras. Alguns animais foram importados de outros zoológicos ou resgatados. O parque oferece safaris em veículos, com o objetivo de mostrar a biodiversidade e promover a educação ambiental, colaborando com projetos de conservação locais.",
      fr: "Le Ridiyagama Safari Park est situé près d'Hambantota, dans le sud du Sri Lanka, et a ouvert en 2016. S'étendant sur environ 200 hectares, c'est le premier safari de l'île conçu avec des enclos ouverts. Le parc est divisé en zones abritant des lions, des tigres, des ours, des girafes et des zèbres. Certains animaux ont été importés d'autres zoos ou secourus. Le parc propose des safaris en véhicule, visant à présenter la biodiversité et à promouvoir l'éducation environnementale, tout en collaborant avec des projets de conservation locaux.",
    },
